class Solution {
public:
    int findMaxFish(std::vector<std::vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        auto dfs = [&](auto& self, int r, int c) -> int {
            if (r < 0 || r >= m || c < 0 || c >= n || grid[r][c] == 0) return 0;
            int fish = grid[r][c];
            grid[r][c] = 0;
            fish += self(self, r - 1, c);
            fish += self(self, r + 1, c);
            fish += self(self, r, c - 1);
            fish += self(self, r, c + 1);
            return fish;
        };
        int max_fish = 0;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] > 0) {
                    max_fish = std::max(max_fish, dfs(dfs, r, c));
                }
            }
        }
        return max_fish;
    }
};

class Solution {
    public int findMaxFish(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int maxFish = 0;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] > 0) {
                    maxFish = Math.max(maxFish, dfs(grid, r, c, m, n));
                }
            }
        }
        return maxFish;
    }

    private int dfs(int[][] grid, int r, int c, int m, int n) {
        if (r < 0 || r >= m || c < 0 || c >= n || grid[r][c] == 0) return 0;
        int fish = grid[r][c];
        grid[r][c] = 0;
        fish += dfs(grid, r - 1, c, m, n);
        fish += dfs(grid, r + 1, c, m, n);
        fish += dfs(grid, r, c - 1, m, n);
        fish += dfs(grid, r, c + 1, m, n);
        return fish;
    }
}

var findMaxFish = function(grid) {
    const m = grid.length, n = grid[0].length;
    function dfs(r, c) {
